import { MyStarsClient } from "@mystars-tg/faas-sdk";

const client = MyStarsClient.production(process.env.MYSTARS_API_KEY!);

// Pass a STABLE idempotencyKey = your own order id so a retry returns
// the SAME order instead of creating a duplicate.
const order = await client.createOrder(
  { type: "stars", recipient: { username: "durov" }, quantity: 500, payment_currency: "ton" },
  { idempotencyKey: `order-${myOrderId}` },
);
console.log(order.payment); // amount, pay_to_address, memo

import { MyStarsClient } from "@mystars-tg/faas-sdk";

const client = MyStarsClient.production(process.env.MYSTARS_API_KEY!);

// Auto-paginating async iterator — the cursor is handled for you.
for await (const order of client.listOrders({ status: "awaiting_payment", limit: 50 })) {
  console.log(order.order_id, order.status);
}

import { MyStarsClient } from "@mystars-tg/faas-sdk";

const client = MyStarsClient.production(process.env.MYSTARS_API_KEY!);

const order = await client.getOrder("7c9e6679-7425-40de-944b-e07fc1f90ae7");
console.log(order.status);

import { MyStarsClient } from "@mystars-tg/faas-sdk";

const client = MyStarsClient.production(process.env.MYSTARS_API_KEY!);

const result = await client.cancelOrder("7c9e6679-7425-40de-944b-e07fc1f90ae7");
console.log(result.status); // "cancelled"

import { MyStarsClient } from "@mystars-tg/faas-sdk";

const client = MyStarsClient.production(process.env.MYSTARS_API_KEY!);

const check = await client.checkRecipient({
  type: "stars",
  recipient: { username: "durov" },
});
if (!check.eligible) throw new Error(check.reason ?? "ineligible");

import { MyStarsClient } from "@mystars-tg/faas-sdk";

const client = MyStarsClient.production(process.env.MYSTARS_API_KEY!);

const quote = await client.getPricing({
  type: "stars",
  quantity: 500,
  payment_currency: "ton",
});
console.log(`pay ${quote.amount} ${quote.currency}`);

import { MyStarsClient } from "@mystars-tg/faas-sdk";

const client = MyStarsClient.production(process.env.MYSTARS_API_KEY!);

const batch = await client.getPricingBatch({
  quantities: [50, 100, 500],
  payment_currency: "usdt_ton",
});
for (const q of batch.quotes) console.log(q.quantity, q.amount);

